import {gamesTableNav} from './shutters-ui.mjs';
import {pileRules,pileDials,pileSource} from './seed-pile-content.mjs';
import {gamesView,pilePosition,newPileGame,takePile,brambleTake,startPile,movePile,explainPile,keepPileNote,resumePile,removePileRecord,readablePileNote,validPileSource} from './seed-pile-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null;
export function resetPileVisit(){visit=null;}
const seed='<span class="pile-seed"></span>';
function seeds(n){return `<div class="pile-seeds" aria-hidden="true">${Array.from({length:Math.ceil(n/5)},(_,i)=>`<div class="pile-five">${seed.repeat(Math.min(5,n-i*5))}</div>`).join('')}</div>`;}
const bramble=`<svg class="pile-bramble" viewBox="0 0 180 170" aria-hidden="true"><path d="M40 151Q35 109 67 105H112Q143 113 147 151" fill="#56355c"/><path d="M56 70Q39 79 47 121M117 70Q136 86 125 123" fill="none" stroke="#44302b" stroke-width="15" stroke-linecap="round"/><ellipse cx="87" cy="76" rx="35" ry="37" fill="#d49b77"/><path d="M51 71Q43 39 80 35Q116 31 125 65L105 48L82 62L65 51Z" fill="#44302b"/><path d="M55 38L83 4L105 31L132 41Q90 60 33 44Z" fill="#56355c"/><path d="M57 35L108 32" stroke="#e9b84a" stroke-width="7"/><circle cx="75" cy="76" r="3" fill="#302b2c"/><circle cx="100" cy="76" r="3" fill="#302b2c"/><path d="M78 92Q88 100 99 90" fill="none" stroke="#6b3f40" stroke-width="3" stroke-linecap="round"/><path d="M57 130L69 153M116 130L108 153" stroke="#d49b77" stroke-width="13" stroke-linecap="round"/><ellipse cx="151" cy="115" rx="15" ry="19" fill="#273b3c"/><path d="M148 103Q136 120 151 126L158 118" fill="#f7f5eb"/><circle cx="155" cy="93" r="10" fill="#273b3c"/><circle cx="158" cy="91" r="2" fill="white"/><path d="M164 94l12 4-12 2M148 130l-10 23 16-19" fill="#273b3c"/></svg>`;
const result=g=>{const p=pilePosition(g);return !p?'Earlier game':p.winner?(p.winner==='child'?g.source.childWin:g.source.brambleWin):`${p.left} seeds left; ${p.turn==='child'?'your':'Bramble’s'} turn`;};
export const pileEntry=()=>'<aside class="pile-invite"><div aria-hidden="true">🌱</div><div><h2>Bramble has brought a game.</h2><p>A handful of seeds. Two players. What will you leave for your rival?</p><a class="secondary" href="#orchard/games">Sit at the Games Table</a></div></aside>';
function history(r){
 if(!r)return '';
 return `<details class="pile-history"><summary>Earlier games and notes</summary><p>Resume a game, or download all your notes before removing a record. No wins or losses are added up.</p>${r.earlier.length?'<h3>Earlier games</h3>':''}${r.earlier.map((g,i)=>pilePosition(g)?`<div class="pile-record"><p>${esc(g.source.title)} · ${esc(result(g))}</p><button type="button" data-pile-resume="${i}">Resume</button><button type="button" data-pile-remove="earlier:${i}">Remove this game</button></div>`:'<p>An earlier record is kept unchanged in your notes download.</p>').join('')}${r.notes.map((n,i)=>readablePileNote(n)?`<div class="pile-record"><p>${esc(n.text||'A game we played.')}<br><small>${esc(n.game.source.title)} · ${esc(result(n.game))}${n.game.support.length?' · Bramble’s explanation was available.':''}</small></p><button type="button" data-pile-remove="notes:${i}">Remove this note</button></div>`:'<p>An earlier note is kept unchanged in your download.</p>').join('')}<a href="#notes">Download from Grown-up notes</a></details>`;
}
function setup(v){const g=v.current,rule=pileRules.find(r=>g&&r.maxTake===g.source.maxTake&&r.lastLoses===g.source.lastLoses)?.id||'pile';return `<div class="pile-setup"><div class="pile-welcome">${bramble}<h1 id="pile-title" tabindex="-1">The Games Table</h1><p>“I brought a game,” says Bramble.<br>“Sit down. You can choose how hard I try.”</p>${seeds(13)}</div><form data-pile-form><h2>Set out the seeds</h2><label>The rules<select name="variant">${pileRules.map(r=>`<option value="${r.id}"${r.id===rule?' selected':''}>${esc(r.title)}</option>`).join('')}</select></label><label>Seeds in the pile <span>(5–30)</span><input name="start" type="number" min="5" max="30" step="1" value="${g?.start||13}" required inputmode="numeric"></label><label>Who starts?<select name="first"><option value="child"${g?.first!=='bramble'?' selected':''}>I’ll go first</option><option value="bramble"${g?.first==='bramble'?' selected':''}>Bramble goes first</option></select></label><label>How hard should Bramble try?<select name="dial">${pileDials.map(([id,label])=>`<option value="${id}"${id===(g?.dial||'attention')?' selected':''}>${esc(label)}</option>`).join('')}</select></label><p class="pile-dial-help">${pileDials.map(([,label,detail])=>`${esc(label)}: ${esc(detail)}`).join('<br>')}</p><button class="primary" type="submit">Put the seeds on the table</button>${v.current?'<button type="button" data-pile-back>Return to our waiting game</button>':''}<p class="tiny">With perfect play, who starts can decide the winner. Finding out why is part of the game.</p></form></div>`;}
function board(g,practice=false){
 const p=pilePosition(g),last=g.moves.at(-1);
 const announcement=p.winner?(p.winner==='child'?g.source.childWin:g.source.brambleWin):p.turn==='child'?'Your turn. What will you take?':'Bramble’s turn. Ready to see her move?';
 return `<header class="pile-board-head">${bramble}<div><p>${practice?'Practice board · your waiting game is unchanged':'Bramble’s Seed Pile'}</p><h1 id="pile-title" tabindex="-1">${esc(g.source.title)}</h1><p class="pile-rule">${esc(g.source.rule)}</p></div></header><div class="pile-table"><div class="pile-count"><strong>${p.left}</strong><span>${p.left===1?'seed':'seeds'} left</span></div>${seeds(p.left)}<p class="pile-last">${last?`${last.who==='child'?'You':'Bramble'} took ${last.take}.`:'The seeds are ready.'}</p></div><h2 id="pile-turn" role="status" aria-live="polite" tabindex="-1">${esc(announcement)}</h2>${!p.winner?`<div class="pile-takes" aria-label="Take seeds">${Array.from({length:g.source.maxTake},(_,i)=>i+1).map(t=>`<button type="button" data-pile-take="${t}"${p.turn!=='child'||t>p.left?' disabled':''}><span aria-hidden="true">${seed.repeat(t)}</span>Take ${t}</button>`).join('')}</div>${p.turn==='bramble'?'<button type="button" class="primary" data-pile-bramble>Let Bramble play</button>':''}`:`<p class="pile-ending">${g.source.lastLoses?`${last.who==='child'?'You':'Bramble'} took the last seed, so ${last.who==='child'?'Bramble wins':'you win'}.`:'The last seed has been taken. Another game can go a different way.'}</p>${!practice?`<form data-pile-note><label>A thought to keep <span>(optional)</span><textarea name="note" rows="2" maxlength="1000" placeholder="I noticed… Next time I’ll try…"${g.noteKept?' disabled':''}></textarea></label><button type="submit"${g.noteKept?' disabled':''}>${g.noteKept?'Note kept':'Keep a game note'}</button></form>`:''}`}${!practice?`<div class="pile-actions"><button type="button" data-pile-new>Change the game / play again</button><button type="button" data-pile-explain>Bramble explains her plan</button></div>`:'<button type="button" class="primary" data-pile-end-practice>Back to Bramble’s explanation</button>'}${g.moves.length?`<details class="pile-moves"><summary>How this game went</summary><ol>${g.moves.map(m=>`<li>${m.who==='child'?'You':'Bramble'} took ${m.take}.</li>`).join('')}</ol></details>`:''}`;
}
function lesson(v){
 const l=v.root?.lesson;
 if(!l||!validPileSource(l.source)||!Number.isInteger(l.step)||l.step<0||l.step>3)return '<p>This earlier explanation is unavailable. Your game is unchanged.</p><button type="button" data-pile-back>Return to game</button>';
 const f=l.source.frames[l.step];
 return `<div class="pile-lesson"><header>${bramble}<h1 id="pile-title" tabindex="-1">Bramble explains</h1><p>${esc(l.source.rule)}</p></header><div class="pile-table">${seeds(f.pile)}<strong>${f.pile} seeds</strong></div><p class="pile-thought" id="pile-thought" tabindex="-1">${esc(f.text)}</p><nav aria-label="Bramble’s explanation"><button type="button" data-pile-step="${l.step-1}"${l.step===0?' disabled':''}>Back</button><span>Thought ${l.step+1} of 4</span>${l.step<3?`<button type="button" class="primary" data-pile-step="${l.step+1}">Next thought</button>`:'<button type="button" class="primary" data-pile-practice>Try it on a practice board</button>'}</nav><button type="button" data-pile-back>Return to our game</button><p class="tiny">This is a supplied strategy. The practice board keeps no result.</p></div>`;
}
export function pilePage(state,owner){
 if(!visit||visit.state!==state||visit.owner!==owner)visit={state,owner,page:'game',practice:null,remove:null,message:''};
 const v=gamesView(state),g=v.current;
 const content=visit.practice?board(visit.practice,true):visit.page==='lesson'?lesson(v):visit.page==='setup'||!g?setup(v):board(g);
 return `<section class="pile-page" data-pile-root><a class="back" href="#orchard">Back to the Orchard</a>${gamesTableNav('pile')}${v.unsupported||v.root?.current&&!g?'<p class="pile-warning">An earlier Games Table record is kept unchanged in your download. Starting a new game will retain it.</p>':''}${content}${visit.remove?'<div class="pile-confirm" role="group" aria-label="Remove this record?"><p>Remove this one record? Download your notes first if you want to keep it. The current game and other places stay here.</p><button type="button" data-pile-confirm>Remove this record</button><button type="button" data-pile-cancel>Keep it</button></div>':''}<p id="pile-status" role="status" tabindex="-1">${esc(visit.message)}</p>${!v.unsupported?history(v.root):''}<p class="tiny">No timer. No running score. You can leave and return to your pile.</p></section>`;
}
export function pileNotes(state){
 if(!Object.hasOwn(state,'games'))return '';
 const v=gamesView(state);return `<details class="panel"><summary>Games Table: seeds and strategy notes</summary><p>Game outcomes are not a math level or an assessment. Reading Bramble’s plan supplies a strategy; it is separate from independent reasoning.</p>${v.current?`<p>${esc(result(v.current))}</p>`:'<p>Earlier unsupported work remains in the download.</p>'}<a href="#orchard/games">Return to the Games Table</a></details>`;
}
export function bindPile(state,ctx){
 const root=document.querySelector('[data-pile-root]');if(!root||!visit)return;
 const captured=visit,owner=ctx.explorerId(),rootRef=state.games;
 const live=()=>root.isConnected&&document.querySelector('[data-pile-root]')===root&&location.hash==='#orchard/games'&&visit===captured&&visit.state===state&&ctx.explorerId()===owner&&ctx.isActive()&&state.games===rootRef;
 const render=(selector='#pile-title')=>{ctx.render();ctx.focus(selector);};
 const status=message=>{const p=root.querySelector('#pile-status');p.textContent=message;p.focus();};
 const act=(fn,selector='#pile-turn')=>{if(!live())return;visit.message='';visit.remove=null;if(!fn()){status(gamesView(state).unsupported?'This earlier record cannot be replaced safely here. Download your notes for a copy, then use a separate explorer for a fresh game. Nothing was changed.':'This change cannot fit safely in your notes. Your work is unchanged. To free space, remove chosen earlier games or notes; download a copy first if you want to keep them. You can also use a separate explorer.');return;}ctx.save();render(selector);};
 root.querySelector('[data-pile-form]')?.addEventListener('submit',e=>{e.preventDefault();if(!live())return;const f=new FormData(e.target);act(()=>startPile(state,{variant:f.get('variant'),start:Number(f.get('start')),first:f.get('first'),dial:f.get('dial')},ctx.canExport)&&((visit.page='game'),true));});
 root.querySelectorAll('[data-pile-take]').forEach(b=>b.onclick=()=>{
  if(!live())return;
  if(visit.practice){const next=takePile(visit.practice,'child',Number(b.dataset.pileTake));if(next){visit.practice=next;render('#pile-turn');}}
  else act(()=>movePile(state,'child',Number(b.dataset.pileTake),ctx.canExport));
 });
 root.querySelector('[data-pile-bramble]')?.addEventListener('click',()=>{
  if(!live())return;
  if(visit.practice){const next=takePile(visit.practice,'bramble',brambleTake(visit.practice));if(next){visit.practice=next;render('#pile-turn');}}
  else act(()=>movePile(state,'bramble',null,ctx.canExport));
 });
 root.querySelector('[data-pile-new]')?.addEventListener('click',()=>{if(live()){visit.page='setup';render();}});
 root.querySelector('[data-pile-back]')?.addEventListener('click',()=>{if(live()){visit.page='game';visit.practice=null;render();}});
 root.querySelector('[data-pile-explain]')?.addEventListener('click',()=>act(()=>explainPile(state,gamesView(state).current?.source.id||'pile',0,ctx.canExport)&&((visit.page='lesson'),true),'#pile-title'));
 root.querySelectorAll('[data-pile-step]').forEach(b=>b.onclick=()=>act(()=>explainPile(state,'pile',Number(b.dataset.pileStep),ctx.canExport),'#pile-thought'));
 root.querySelector('[data-pile-practice]')?.addEventListener('click',()=>{if(!live())return;const s=gamesView(state).root?.lesson?.source;if(!validPileSource(s))return;visit.practice={...newPileGame({start:6,dial:'plan',support:['explanation']}),source:structuredClone(s)};render();});
 root.querySelector('[data-pile-end-practice]')?.addEventListener('click',()=>{if(live()){visit.practice=null;visit.page='lesson';render();}});
 root.querySelector('[data-pile-note]')?.addEventListener('submit',e=>{e.preventDefault();act(()=>{if(!keepPileNote(state,new FormData(e.target).get('note'),ctx.canExport))return false;visit.message='Your game note is kept.';return true;},'#pile-status');});
 root.querySelectorAll('[data-pile-resume]').forEach(b=>b.onclick=()=>act(()=>resumePile(state,Number(b.dataset.pileResume),ctx.canExport)&&((visit.page='game'),(visit.practice=null),true)));
 root.querySelectorAll('[data-pile-remove]').forEach(b=>b.onclick=()=>{if(live()){visit.remove=b.dataset.pileRemove;render('[data-pile-cancel]');}});
 root.querySelector('[data-pile-cancel]')?.addEventListener('click',()=>{if(live()){visit.remove=null;render();}});
 root.querySelector('[data-pile-confirm]')?.addEventListener('click',()=>{if(!visit.remove)return;const [kind,index]=visit.remove.split(':');act(()=>removePileRecord(state,kind,Number(index),ctx.canExport)&&((visit.remove=null),true),'#pile-title');});
}
